mapper.select:
SELECT id, name, contact_name, phone, email, tax_code, is_active, note, created_at, updated_at
FROM suppliers
WHERE id = #{id}

SELECT * FROM suppliers


        AND (
        LOWER(name) LIKE LOWER(CONCAT('%', #{keyword}, '%'))
        OR LOWER(contact_name) LIKE LOWER(CONCAT('%', #{keyword}, '%'))
        OR LOWER(tax_code) LIKE LOWER(CONCAT('%', #{keyword}, '%'))
        OR LOWER(email) LIKE LOWER(CONCAT('%', #{keyword}, '%'))
        )


ORDER BY ${sortField} ${sortOrder}
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM suppliers
AND ( LOWER(name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(contact_name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(tax_code) LIKE LOWER(CONCAT('%', #{keyword}, '%')) )
AND is_active = #{isActive}
